        check(0.3333333333333333, 'G', -1, 64, "0.3333333333333333");
        check(0.5, 'g', -1, 64, "0.5");
        check(0.5, 'G', -1, 64, "0.5");
        check(0.25, 'g', -1, 64, "0.25");
        check(0.25, 'G', -1, 64, "0.25");
        check(2.5, 'g', -1, 64, "2.5");
        check(2.5, 'G', -1, 64, "2.5");
        check(123.456, 'g', -1, 64, "123.456");
        check(123.456, 'G', -1, 64, "123.456");
        check(0.30000000000000004, 'g', -1, 64, "0.30000000000000004");
        check(0.30000000000000004, 'G', -1, 64, "0.30000000000000004");
        check(1.0000000000000002, 'g', -1, 64, "1.0000000000000002");
        check(1.0000000000000002, 'G', -1, 64, "1.0000000000000002");
        check(0.9999999999999999, 'g', -1, 64, "0.9999999999999999");
