        check(2.718281828459045, 'g', -1, 64, "2.718281828459045");
        check(2.718281828459045, 'G', -1, 64, "2.718281828459045");
        check(1.4142135623730951, 'g', -1, 64, "1.4142135623730951");
        check(1.4142135623730951, 'G', -1, 64, "1.4142135623730951");
        check(1.5, 'g', -1, 64, "1.5");
        check(1.5, 'G', -1, 64, "1.5");
        check(0.0001, 'g', -1, 64, "0.0001");
        check(0.0001, 'G', -1, 64, "0.0001");
        check(9.9999e-05, 'g', -1, 64, "9.9999e-05");
        check(9.9999e-05, 'G', -1, 64, "9.9999E-05");
        check(1e-05, 'g', -1, 64, "1e-05");
        check(1e-05, 'G', -1, 64, "1E-05");
        check(1.234e-05, 'g', -1, 64, "1.234e-05");
        check(1.234e-05, 'G', -1, 64, "1.234E-05");
        check(123456, 'g', -1, 64, "123456");
        check(123456, 'G', -1, 64, "123456");
