        check(1e+06, 'g', -1, 64, "1e+06");
        check(1e+06, 'G', -1, 64, "1E+06");
        check(1e+20, 'g', -1, 64, "1e+20");
        check(1e+20, 'G', -1, 64, "1E+20");
        check(1e+21, 'g', -1, 64, "1e+21");
