        check(1.7976931348623157e+308, 'g', -1, 64, "1.7976931348623157e+308");
        check(1.7976931348623157e+308, 'G', -1, 64, "1.7976931348623157E+308");
        check(2.2250738585072014e-308, 'g', -1, 64, "2.2250738585072014e-308");
        check(2.2250738585072014e-308, 'G', -1, 64, "2.2250738585072014E-308");
