        check(3.45876451382054e-309, 'g', -1, 64, "3.45876451382054e-309");
        check(3.45876451382054e-309, 'G', -1, 64, "3.45876451382054E-309");
        check(7.4e-323, 'g', -1, 64, "7.4e-323");
        check(7.4e-323, 'G', -1, 64, "7.4E-323");
        check(-0.1, 'g', -1, 64, "-0.1");
        check(-0.1, 'G', -1, 64, "-0.1");
        check(-123.456, 'g', -1, 64, "-123.456");
        check(-123.456, 'G', -1, 64, "-123.456");
        check(-1e+21, 'g', -1, 64, "-1e+21");
