        check(0.3333333333333333, 'f', -1, 64, "0.3333333333333333");
        check(0.5, 'e', -1, 64, "5e-01");
        check(0.5, 'E', -1, 64, "5E-01");
        check(0.5, 'f', -1, 64, "0.5");
        check(0.25, 'e', -1, 64, "2.5e-01");
        check(0.25, 'E', -1, 64, "2.5E-01");
        check(0.25, 'f', -1, 64, "0.25");
        check(2.5, 'e', -1, 64, "2.5e+00");
        check(2.5, 'E', -1, 64, "2.5E+00");
        check(2.5, 'f', -1, 64, "2.5");
        check(123.456, 'e', -1, 64, "1.23456e+02");
        check(123.456, 'E', -1, 64, "1.23456E+02");
        check(123.456, 'f', -1, 64, "123.456");
        check(0.30000000000000004, 'e', -1, 64, "3.0000000000000004e-01");
