        checkX(Double.NEGATIVE_INFINITY, 'X', 4, 32, "-Inf");
        checkX(Double.NEGATIVE_INFINITY, 'X', 13, 32, "-Inf");
        checkX(Double.NaN, 'x', -1, 32, "NaN");
