        checkB(1e+100, 64, "5147557589468029p+280");
        checkB(1e+300, 64, "6724873095247260p+944");
        checkB(1.7976931348623157e+308, 64, "9007199254740991p+971");
        checkB(2.2250738585072014e-308, 64, "4503599627370496p-1074");
        checkB(2.225073858507201e-308, 64, "4503599627370495p-1074");
        checkB(1.1125369292536007e-308, 64, "2251799813685248p-1074");
        checkB(1e-310, 64, "20240225330731p-1074");
