        checkC(0, -0.0, 'e', 3, 128, "(0.000e+00-0.000e+00i)");
        checkC(0, -0.0, 'E', 1, 128, "(0.0E+00-0.0E+00i)");
        checkC(-0.0, 0, 'g', -1, 64, "(-0+0i)");
        checkC(-0.0, 0, 'G', -1, 64, "(-0+0i)");
